const ALIASES={埃及:'egypt',egypt:'egypt',cairo:'egypt',开罗:'egypt',吉萨:'egypt',京都:'kyoto',kyoto:'kyoto',日本:'kyoto',北京:'beijing',beijing:'beijing',西安:'xian',xian:'xian',巴黎:'paris',paris:'paris',法国:'paris'};
const app=document.getElementById('app');
const state={view:'discover',tab:'discover',tripId:null,detail:null,search:'',results:[],searchError:'',searching:false,placeTab:'all',planRegion:'出境',weather:null,weatherFor:null};
let toastTimer,searchSeq=0;
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const todayISO=()=>new Date().toISOString().slice(0,10);
const addDays=(iso,n)=>{const d=new Date(`${iso}T12:00:00`);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const prettyDate=iso=>new Date(`${iso}T12:00:00`).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
const duration=t=>Math.max(1,Math.round((new Date(`${t.end}T12:00:00`)-new Date(`${t.start}T12:00:00`))/86400000)+1);
const uid=()=>globalThis.crypto?.randomUUID?.()||`t${Date.now()}${Math.random().toString(36).slice(2)}`;
function storeGet(){try{return JSON.parse(localStorage.getItem('xiangye-trips')||'[]')}catch{return []}}
function storeSet(trips){localStorage.setItem('xiangye-trips',JSON.stringify(trips))}
function trips(){return storeGet().sort((a,b)=>b.created-a.created)}
function trip(){return trips().find(t=>t.id===state.tripId)||trips()[0]||null}
function saveTrip(t){const all=storeGet();const i=all.findIndex(x=>x.id===t.id);if(i<0)all.push(t);else all[i]=t;storeSet(all)}
function matchingCatalog(q){const k=String(q).trim().toLowerCase();return CATALOG[ALIASES[k]]?{key:ALIASES[k],...CATALOG[ALIASES[k]]}:Object.entries(CATALOG).map(([key,d])=>({key,...d})).find(d=>d.name.includes(k)||d.places.some(p=>p.name===k))||null}
function getDestination(t){return t?.destinationData||CATALOG[t?.key]||null}
function placeKey(p){return `${p.name}|${p.city||''}`}
function findPlace(t,key){return getDestination(t)?.places?.find(p=>placeKey(p)===key)}
function notify(message){const box=document.getElementById('toast');box.textContent=message;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),3000)}
function goto(view,opts={}){state.view=view;state.tab=opts.tab||({discover:'discover',search:'discover',destination:'discover',detail:'discover',trips:'trips',trip:'trips',plan:'plan',checklist:'checklist',profile:'profile'}[view]||'discover');if(opts.tripId)state.tripId=opts.tripId;if(opts.detail)state.detail=opts.detail;render();window.scrollTo({top:0,behavior:'instant'});app.focus({preventScroll:true})}
function updateTabs(){document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===state.tab;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
function image(src,alt,cls=''){const local=window.XIANGYE_PHOTOS?.[alt],chosen=local||src;return `<span class="photo-cover ${cls}" role="img" aria-label="${escapeHtml(alt)}">${chosen?`<img src="${escapeHtml(chosen)}" alt="" loading="lazy" onerror="this.remove()">`:''}<span class="photo-cover-label">${escapeHtml(alt)}</span></span>`}
function placeCard(p,index){const key=state.view==='discover'?(trip()?.key||'kyoto'):(state.destination?.key||'kyoto');return `<button class="place-card" data-action="detail" data-place="${escapeHtml(placeKey(p))}" data-key="${escapeHtml(key)}" data-index="${index}">${image(p.photo,p.name)}<strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.city||'')} · ${escapeHtml(p.kind||'景点')}</small></button>`}
function searchForm(value=''){return `<form class="search-form" id="searchForm"><input id="searchInput" name="q" value="${escapeHtml(value)}" aria-label="搜索城市、景点或博物馆" placeholder="搜索城市、景点或博物馆" autocomplete="off"><button type="submit" aria-label="搜索">⌕</button></form>`}
function renderDiscover(){const t=trip(),d=t&&getDestination(t),featured=CATALOG.egypt,near=d||CATALOG.kyoto;return `<p class="eyebrow">今天，想去哪里</p><h1 class="display">把日子过成<br><em>一段路。</em></h1>${searchForm()}<button class="hero-photo" data-action="destination" data-key="egypt" style="--hero-image:url('${featured.photo}')"><span><small>本周灵感 · 历史与河流</small><strong>埃及，沿尼罗河走</strong><small>开罗 · 吉萨 · 卢克索　↗</small></span></button><div class="section-heading"><h2 class="section-title">${d?'目的地值得去':'看看这些地方'}</h2><button class="text-button" data-action="all-places" data-key="${near.key||t?.key||'kyoto'}">看全部 ↗</button></div><div class="scroll-cards">${near.places.map(placeCard).join('')}</div><div class="section-heading"><h2 class="section-title">你的下一站</h2>${t?`<button class="text-button" data-action="edit-trip" data-id="${t.id}">编辑</button>`:''}</div>${t?`<div class="trip-summary"><div class="badge-date">${escapeHtml(t.start.slice(8))}<small>${escapeHtml(t.start.slice(5,7))}月</small></div><div><strong>${escapeHtml(t.origin)} → ${escapeHtml(t.destination)}</strong><p>${prettyDate(t.start)}出发 · ${duration(t)}天</p></div><button data-action="open-trip" data-id="${t.id}">查看</button></div>`:`<div class="empty">还没有行程。选一个目的地，开始规划自己的路线。<p><button class="primary" data-action="plan">开始规划</button></p></div>`}<div class="section-heading"><h2 class="section-title">更多目的地</h2></div><div class="destination-grid">${['beijing','xian','paris','kyoto'].map(k=>`<button class="place-card" data-action="destination" data-key="${k}">${image(CATALOG[k].photo,CATALOG[k].name)}<strong>${CATALOG[k].name}</strong><small>${CATALOG[k].region} · 探索景点</small></button>`).join('')}</div>`}
function renderSearch(){return `<button class="text-button" data-action="home">← 返回发现</button><h1 class="page-title">找一个想去的地方</h1>${searchForm(state.search)}${state.searching?'<p class="loading">正在搜索目的地和景点…</p>':''}${state.searchError?`<p class="error">${escapeHtml(state.searchError)}</p>`:''}<div id="searchResults">${state.results.length?state.results.map((r,i)=>`<button class="search-result" data-action="search-result" data-index="${i}">${image(r.photo,r.name)}<span><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(r.subtitle||'目的地')}</small></span><b>↗</b></button>`).join(''):state.search&&!state.searching?'<div class="empty">没有找到匹配项。试试城市名称，例如“开罗”或“巴黎”。</div>':'<p class="sub">可以搜索城市、国家、景点和博物馆。</p>'}</div>`}
function renderDestination(){const d=state.destination;if(!d)return renderDiscover();const ps=d.places||[];const chosen=state.placeTab==='all'?ps:ps.filter(p=>p.kind?.includes('博物馆'));return `<button class="text-button" data-action="home">← 返回发现</button>${image(d.photo,d.name,'detail-image')}<h1 class="page-title">${escapeHtml(d.name)}</h1><p class="sub">${escapeHtml(d.country||d.name)} · ${escapeHtml(d.region||'目的地')}</p><p class="article-text">${escapeHtml(d.intro||'收集当地值得慢慢看的地方，按你的时间规划路线。')}</p><div class="actions"><button class="primary" data-action="plan-for" data-key="${escapeHtml(d.key||'')}">规划这里的旅行</button><button class="secondary" data-action="map-destination">打开地图</button></div><div class="section-heading"><h2 class="section-title">所有值得去</h2><span class="muted small">${ps.length}个地点</span></div><div class="tab-nested"><button data-action="filter-places" data-filter="all" class="${state.placeTab==='all'?'selected':''}">全部</button><button data-action="filter-places" data-filter="museum" class="${state.placeTab==='museum'?'selected':''}">博物馆</button></div>${chosen.length?`<div class="destination-grid">${chosen.map(placeCard).join('')}</div>`:'<div class="empty">这里暂时没有收录博物馆，可以搜索具体名称。</div>'}<p class="notice">开放时间、门票和签证政策可能变动，出发前请以官方信息为准。</p>`}
function renderDetail(){const p=state.detail,d=state.destination;if(!p)return renderDiscover();const t=trip();const map=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${p.name} ${p.city||''}`)}`;return `<button class="text-button" data-action="back-detail">← 返回${escapeHtml(d?.name||'搜索')}</button>${image(p.photo,p.name,'detail-image')}<h1 class="page-title">${escapeHtml(p.name)}</h1><p class="sub">${escapeHtml(p.city||d?.name||'')} · ${escapeHtml(p.kind||'景点')}</p><div class="chip-row"><span class="chip">建议游玩 ${escapeHtml(p.time||'2小时')}</span><span class="chip">参考门票 ¥${Number(p.cost||0)}</span>${p.kind?.includes('博物馆')?'<span class="chip">博物馆</span>':''}</div><h2 class="section-title">来这里，看什么</h2><p class="article-text">${escapeHtml(p.summary||'了解这里的历史与文化。详细开放信息请通过官方渠道核实。')}</p><div id="wikiDetail" class="small muted"></div><div class="actions"><button class="primary" data-action="add-place" data-place="${escapeHtml(placeKey(p))}">${t?'加入当前行程':'为这里建行程'}</button><button class="secondary" data-action="external-map" data-url="${escapeHtml(map)}">地图路线</button></div><p class="notice">门票为人民币粗略参考值，并非实时票价。开放时间请点击地图或官网核实。</p>`}
function planDefaults(){const t=state.editTrip||null,d=state.planDestination||getDestination(t);return {origin:t?.origin||'上海',destination:t?.destination||d?.name||'',start:t?.start||addDays(todayISO(),20),end:t?.end||addDays(todayISO(),24),people:t?.people||2,budget:t?.budget||10000,region:t?.region||d?.region||state.planRegion}}
function renderPlan(){const v=planDefaults();return `<h1 class="page-title">${state.editTrip?'编辑这段旅程':'规划一段路'}</h1><p class="sub">从哪里走，什么时候走，想花多少钱。</p><form id="planForm"><span class="small muted">旅行范围</span><div class="segmented"><button type="button" data-action="set-region" data-region="国内" class="${v.region==='国内'?'selected':''}">中国境内</button><button type="button" data-action="set-region" data-region="出境" class="${v.region==='出境'?'selected':''}">出境旅行</button></div><label class="field"><span>出发地</span><input name="origin" value="${escapeHtml(v.origin)}" required></label><label class="field"><span>目的地：城市、国家或景点</span><input name="destination" value="${escapeHtml(v.destination)}" placeholder="例如：埃及、开罗、京都" required></label><div class="field-row"><label class="field"><span>出发日期</span><input type="date" name="start" value="${v.start}" required></label><label class="field"><span>返回日期</span><input type="date" name="end" value="${v.end}" required></label></div><div class="field-row"><label class="field"><span>人数</span><input type="number" name="people" min="1" max="20" value="${v.people}" required></label><label class="field"><span>总预算 ¥</span><input type="number" name="budget" min="0" step="100" value="${v.budget}" required></label></div><label class="field"><span>旅行偏好</span><select name="pace"><option value="slow">慢一点，少走几个地方</option><option value="balanced">适中，经典景点与休息兼顾</option><option value="full">尽量多看一些</option></select></label><button class="primary full" type="submit">${state.editTrip?'保存并重新规划':'生成我的行程'} ↗</button><p id="planError" class="error" role="alert"></p></form><p class="notice">行程是可编辑的初稿。费用为估算，跨城交通、住宿和门票需根据实际预订核对。</p>`}
function renderTrips(){const all=trips();return `<h1 class="page-title">你的行程</h1><p class="sub">走过的、正在准备的，都放在这里。</p>${all.length?all.map(t=>`<button class="trip-button" data-action="open-trip" data-id="${t.id}"><strong>${escapeHtml(t.origin)} → ${escapeHtml(t.destination)}</strong><small>${prettyDate(t.start)}—${prettyDate(t.end)} · ${duration(t)}天 · ${t.people}人</small></button>`).join(''):'<div class="empty">还没有行程。</div>'}<button class="secondary full" data-action="new-trip">＋ 新建旅行</button>`}
function estimated(t){const d=getDestination(t);const n=duration(t),pp=t.people||1;const daily=d?.daily||750;const flight=(d?.flight||2000)*pp;const stay=Math.round(daily*.48*n*pp);const food=Math.round(daily*.25*n*pp);const local=Math.round(daily*.27*n*pp);const tickets=(t.days||[]).flatMap(x=>x.places).reduce((sum,key)=>sum+(findPlace(t,key)?.cost||0),0)*pp;return {flight,stay,food,local,tickets,total:flight+stay+food+local+tickets}}
const weatherLabel=code=>code===0?'晴朗':code<=3?'多云':code<=67?'有雨':code<=77?'有雪':'天气多变';
function renderTrip(){const t=trip();if(!t)return renderTrips();const estimate=estimated(t),d=getDestination(t);return `<button class="text-button" data-action="all-trips">← 所有行程</button><h1 class="page-title">${escapeHtml(t.destination)}，慢慢走</h1><p class="sub">${prettyDate(t.start)}—${prettyDate(t.end)} · ${duration(t)}天 · ${t.people}人</p><div class="actions"><button class="secondary" data-action="edit-trip" data-id="${t.id}">编辑基本信息</button><button class="secondary" data-action="open-destination">探索景点</button></div><div id="weatherPanel" class="notice">天气只显示可查询的预报日期。正在核对…</div><div class="section-heading"><h2 class="section-title">每天怎么走</h2></div>${t.days.map((day,i)=>{const w=state.weatherFor===t.id&&state.weather?.[day.date];return `<article class="day-card"><div class="day-top"><strong>第${i+1}天 · ${prettyDate(day.date)}</strong><span class="weather-line">${w?`${weatherLabel(w.code)} ${w.low}–${w.high}°C`:''}</span></div><p class="small muted">${i===0?'抵达与适应':i===t.days.length-1?'收尾与返程':'景点与城市漫步'}</p><ul class="day-list">${day.places.length?day.places.map(key=>{const p=findPlace(t,key);return `<li><span><b>${escapeHtml(p?.name||key.split('|')[0])}</b><br><small class="muted">${escapeHtml(p?.city||'')} · ${escapeHtml(p?.time||'约2小时')}</small></span><button data-action="remove-place" data-day="${i}" data-place="${escapeHtml(key)}" aria-label="移除${escapeHtml(p?.name||key)}">移除</button></li>`}).join(''):'<li class="muted">这天暂时留白，可以加一个想看的地方。</li>'}</ul><button class="text-button" data-action="choose-place" data-day="${i}">＋ 添加地点</button></article>`}).join('')}<div class="section-heading"><h2 class="section-title">花费估算</h2></div><div class="budget-grid"><div class="card"><span class="small muted">全程估算</span><strong>¥${estimate.total.toLocaleString()}</strong></div><div class="card"><span class="small muted">你的预算</span><strong>¥${Number(t.budget).toLocaleString()}</strong></div></div><p class="small muted">交通 ¥${estimate.flight} · 住宿 ¥${estimate.stay} · 餐饮 ¥${estimate.food} · 市内交通 ¥${estimate.local} · 门票 ¥${estimate.tickets}。按${t.people}人计算，仅供规划。</p>${estimate.total>t.budget?'<p class="notice">目前估算超过预算。可缩短天数、调整住宿或减少跨城段。</p>':''}<div class="actions"><button class="secondary" data-action="checklist">出发清单</button><button class="secondary" data-action="share-trip">分享行程</button></div>${d?.type==='country'&&d.places.some(p=>p.city!==d.center)?'<p class="notice">此路线涉及不同城市，跨城交通未自动预订；请按实际车次或航班调整行程。</p>':''}`}
function renderChoose(){const t=trip(),d=getDestination(t),day=state.chooseDay||0;if(!t||!d)return '<div class="empty">请先建立一段旅行。</div>';return `<button class="text-button" data-action="open-trip" data-id="${t.id}">← 返回行程</button><h1 class="page-title">为第${day+1}天加一个地方</h1><p class="sub">选择后会立即保存到行程。</p>${d.places.map(p=>`<button class="search-result" data-action="assign-place" data-place="${escapeHtml(placeKey(p))}">${image(p.photo,p.name)}<span><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.city)} · ${escapeHtml(p.kind)}</small></span><b>＋</b></button>`).join('')}`}
function checklistItems(t){const abroad=t.region==='出境';return [{id:'id',label:abroad?'检查护照有效期':'携带身份证'},{id:'transport',label:'确认往返交通与车票/机票'},{id:'hotel',label:'确认住宿订单'},{id:'insurance',label:'购买或核对旅行保险'},...(abroad?[{id:'visa',label:'核实签证或入境资格'},{id:'entry',label:'准备入境材料与海关申报'},{id:'money',label:'准备当地支付方式与少量现金'},{id:'mobile',label:'准备境外网络与离线地图'}]:[]),{id:'weather',label:'出发前查看天气并准备衣物'},{id:'medicine',label:'整理常用药、充电器和随身物品'}]}
function renderChecklist(){const t=trip();if(!t)return `<h1 class="page-title">出发清单</h1><div class="empty">先建立行程，清单会按国内或出境旅行生成。</div><button class="primary full" data-action="new-trip">开始规划</button>`;const items=checklistItems(t),custom=t.customItems||[],total=items.length+custom.length,done=items.filter(x=>t.checked?.[x.id]).length+custom.filter(x=>t.checked?.[`custom:${x.id}`]).length;return `<h1 class="page-title">出发清单</h1><p class="sub">${escapeHtml(t.destination)} · ${prettyDate(t.start)}出发</p><div class="card"><strong>已完成 ${done}/${total}</strong><div class="progress"><span style="width:${done/total*100}%"></span></div><p class="small muted">勾选状态会保存在这台设备上。</p></div>${items.map(x=>`<label class="check-row"><input type="checkbox" data-check="${x.id}" ${t.checked?.[x.id]?'checked':''}><span>${x.label}</span></label>`).join('')}<form id="customItemForm" class="search-form" style="margin-top:18px"><input name="item" aria-label="新增准备事项" placeholder="添加自己的准备事项"><button type="submit" aria-label="添加事项">＋</button></form>${custom.map(x=>`<label class="check-row"><input type="checkbox" data-check="custom:${escapeHtml(x.id)}" ${t.checked?.[`custom:${x.id}`]?'checked':''}><span>${escapeHtml(x.label)}</span><button class="text-button" type="button" data-action="remove-custom" data-id="${x.id}">删除</button></label>`).join('')}${t.region==='出境'?`<p class="notice">${escapeHtml(getDestination(t)?.visa||'入境政策会变化。请向目的地官方使领馆核实签证、护照和入境要求。')}</p>`:''}`}
function renderProfile(){const all=trips();return `<h1 class="page-title">我的旅行</h1><p class="sub">把想去的地方和走过的路留在这里。</p><div class="card"><strong>${all.length}</strong> 段已保存行程 <span class="muted small">· 数据仅保存在当前浏览器</span></div><div class="section-heading"><h2 class="section-title">旅行记录</h2></div>${all.length?all.map(t=>`<button class="trip-button" data-action="open-trip" data-id="${t.id}"><strong>${escapeHtml(t.destination)}</strong><small>${prettyDate(t.start)}—${prettyDate(t.end)} · ${duration(t)}天</small></button>`).join(''):'<div class="empty">还没有旅行记录。</div>'}<button class="secondary full" data-action="new-trip">＋ 规划新的旅行</button><div class="section-heading"><h2 class="section-title">关于向野</h2></div><p class="small muted">景点资料来自应用内精选内容或公开百科；天气使用 Open-Meteo 预报。费用为规划估算，不代表实时价格。旅行资料、清单与行程储存在本机浏览器。</p>`}
function render(){updateTabs();const views={discover:renderDiscover,search:renderSearch,destination:renderDestination,detail:renderDetail,plan:renderPlan,trips:renderTrips,trip:renderTrip,choose:renderChoose,checklist:renderChecklist,profile:renderProfile};app.innerHTML=(views[state.view]||renderDiscover)();if(state.view==='trip')loadWeather();if(state.view==='detail')loadWikiDetail()}
function curatedResults(q){const lower=q.toLowerCase();const list=[];for(const [key,d] of Object.entries(CATALOG)){if(d.name.toLowerCase().includes(lower)||d.country.toLowerCase().includes(lower)||key.includes(lower)){list.push({type:'destination',key,name:d.name,subtitle:`${d.country} · ${d.places.length}个精选地点`,photo:d.photo})}for(const p of d.places){if(p.name.toLowerCase().includes(lower)||p.query?.toLowerCase().includes(lower)){list.push({type:'place',key,place:p,name:p.name,subtitle:`${p.city} · ${p.kind}`,photo:p.photo})}}}return list}
async function fetchJson(url,timeout=7000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{signal:controller.signal});if(!r.ok)throw new Error(`HTTP ${r.status}`);return await r.json()}finally{clearTimeout(timer)}}
async function onlineSearch(q){const out=[];const geoUrl=`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=5&language=zh&format=json`;const wikiUrl=`https://zh.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(q)}&gsrlimit=8&prop=pageimages%7Cextracts%7Ccoordinates&pithumbsize=300&exintro=1&explaintext=1&exsentences=2&format=json&origin=*`;
  const results=await Promise.allSettled([fetchJson(geoUrl),fetchJson(wikiUrl)]);
  if(results[0].status==='fulfilled')for(const g of results[0].value.results||[]){out.push({type:'remote-destination',name:g.name,subtitle:`${g.country||''}${g.admin1?' · '+g.admin1:''} · 城市`,lat:g.latitude,lon:g.longitude,country:g.country||'',countryCode:g.country_code||''})}
  if(results[1].status==='fulfilled')for(const p of Object.values(results[1].value.query?.pages||{})){if(!p.title)continue;out.push({type:'remote-place',name:p.title,subtitle:(p.extract||'百科资料').slice(0,46),summary:p.extract||'',photo:p.thumbnail?.source,lat:p.coordinates?.[0]?.lat,lon:p.coordinates?.[0]?.lon,query:p.title})}
  return {items:out,failed:results.every(r=>r.status==='rejected')}
}
async function performSearch(q){state.search=q.trim();state.searching=true;state.searchError='';state.results=curatedResults(state.search);goto('search');if(!state.search){state.searching=false;state.searchError='请输入城市、国家、景点或博物馆。';render();return}const seq=++searchSeq;try{const remote=await onlineSearch(state.search);if(seq!==searchSeq||state.view!=='search')return;const names=new Set(state.results.map(r=>r.name.toLowerCase()));for(const item of remote.items){if(!names.has(item.name.toLowerCase())){state.results.push(item);names.add(item.name.toLowerCase())}}if(remote.failed)state.searchError=state.results.length?'在线搜索暂时不可用，下面仍可查看已收录地点。':'在线搜索暂时不可用，请检查网络后重试。'}catch{if(seq===searchSeq)state.searchError='在线搜索暂时不可用，请检查网络后重试。'}finally{if(seq===searchSeq&&state.view==='search'){state.searching=false;render()}}}
function remoteDestination(r){const domestic=r.countryCode==='CN'||r.country==='中国';return {key:`remote:${r.name}`,name:r.name,type:'city',country:r.country||r.name,region:domestic?'国内':'出境',center:r.name,lat:r.lat,lon:r.lon,intro:`探索${r.name}的历史、博物馆与周边去处。你可以先建立行程，再逐步添加想看的地方。`,daily:domestic?650:1000,flight:domestic?1500:4500,places:[],visa:'请通过目的地官方渠道确认入境和签证要求。'}}
function chooseSearchResult(i){const r=state.results[i];if(!r)return;if(r.type==='destination'){openDestination(r.key);return}if(r.type==='place'){openDestination(r.key,false);openPlace(r.place);return}if(r.type==='remote-destination'){state.destination=remoteDestination(r);state.placeTab='all';goto('destination');loadNearby(r);return}if(r.type==='remote-place'){const d={key:`wiki:${r.name}`,name:r.name,region:'待确认',country:'',center:r.name,lat:r.lat,lon:r.lon,places:[],intro:r.summary};state.destination=d;state.detail={name:r.name,city:'',kind:'景点/博物馆',summary:r.summary,photo:r.photo,lat:r.lat,lon:r.lon,query:r.query,time:'约2小时',cost:0};goto('detail')}}
async function loadNearby(r){if(!r.lat||!r.lon)return;const id=state.destination?.key;try{const url=`https://zh.wikipedia.org/w/api.php?action=query&generator=geosearch&ggscoord=${r.lat}%7C${r.lon}&ggsradius=10000&ggslimit=15&prop=pageimages%7Cextracts&pithumbsize=300&exintro=1&explaintext=1&exsentences=2&format=json&origin=*`;const json=await fetchJson(url);if(state.destination?.key!==id)return;state.destination.places=Object.values(json.query?.pages||{}).filter(p=>p.title!==r.name).slice(0,12).map(p=>({name:p.title,city:r.name,kind:/博物馆|museum/i.test(p.title)?'博物馆':'景点',summary:p.extract||'可打开百科了解历史背景。',photo:p.thumbnail?.source,query:p.title,time:'约2小时',cost:0}));render()}catch{if(state.destination?.key===id){state.destination.intro+=' 附近地点暂时无法加载，可通过顶部搜索具体景点。';render()}}}
async function enrichTrip(t){if(getDestination(t)?.places?.length)return;const id=t.id;try{let d=getDestination(t);if(!d.lat||!d.lon){const geo=await fetchJson(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(t.destination)}&count=1&language=zh&format=json`);const first=geo.results?.[0];if(!first)return;d={...d,lat:first.latitude,lon:first.longitude,country:first.country||d.country,region:first.country_code==='CN'?'国内':'出境'}}const url=`https://zh.wikipedia.org/w/api.php?action=query&generator=geosearch&ggscoord=${d.lat}%7C${d.lon}&ggsradius=10000&ggslimit=15&prop=pageimages%7Cextracts&pithumbsize=300&exintro=1&explaintext=1&exsentences=2&format=json&origin=*`;const wiki=await fetchJson(url);d.places=Object.values(wiki.query?.pages||{}).filter(p=>p.title!==d.name).slice(0,12).map(p=>({name:p.title,city:d.name,kind:/博物馆|museum/i.test(p.title)?'博物馆':'景点',summary:p.extract||'可进一步查看百科资料。',photo:p.thumbnail?.source,query:p.title,time:'约2小时',cost:0}));const current=storeGet().find(x=>x.id===id);if(!current)return;current.destinationData=d;if(current.days.every(day=>!day.places.length)){const planned=distributePlaces(d,current.days.length,'balanced');current.days.forEach((day,i)=>day.places=planned[i])}saveTrip(current);if(state.view==='trip'&&state.tripId===id){render();notify('已补充附近景点，可以继续编辑每天的路线。')}}catch{if(state.view==='trip'&&state.tripId===id)notify('在线景点暂时无法加载，你仍可以保存和编辑行程。')}}
function openDestination(key,renderNow=true){state.destination=CATALOG[key]?{key,...CATALOG[key]}:state.destination;state.placeTab='all';if(renderNow)goto('destination')}
function openPlace(p){state.detail=p;goto('detail')}
async function loadWikiDetail(){const p=state.detail;if(!p)return;const box=document.getElementById('wikiDetail');if(!box)return;try{const title=p.query||p.name;const url=`https://zh.wikipedia.org/w/api.php?action=query&titles=${encodeURIComponent(title)}&prop=extracts&exintro=1&explaintext=1&format=json&origin=*`;const json=await fetchJson(url,5500);if(state.detail!==p)return;const page=Object.values(json.query?.pages||{})[0];if(page?.extract&&page.extract.length>80){box.innerHTML=`<p class="article-text">${escapeHtml(page.extract.slice(0,800))}</p><a href="https://zh.wikipedia.org/wiki/${encodeURIComponent(title)}" target="_blank" rel="noopener noreferrer">阅读百科原文 ↗</a>`}else box.innerHTML=`<a href="https://zh.wikipedia.org/wiki/${encodeURIComponent(title)}" target="_blank" rel="noopener noreferrer">查看百科资料 ↗</a>`}catch{box.textContent='百科资料暂时无法连接，以上为已收录简介。'}}
function distributePlaces(d,n,pace){const days=Array.from({length:n},()=>[]);const places=[...(d.places||[])];if(!places.length)return days;const slots=pace==='slow'?1:pace==='full'?3:2;const travelFirst=n>=4,travelLast=n>=4;let day=travelFirst?1:0;for(const p of places){while(day<n-(travelLast?1:0)&&days[day].length>=slots)day++;if(day>=n-(travelLast?1:0))break;days[day].push(placeKey(p))}return days}
function createOrUpdateTrip(form){const data=new FormData(form);const origin=String(data.get('origin')||'').trim(),destination=String(data.get('destination')||'').trim(),start=String(data.get('start')||''),end=String(data.get('end')||'');const error=document.getElementById('planError');if(!origin||!destination||!start||!end){error.textContent='请填写出发地、目的地和日期。';return}if(end<start){error.textContent='返回日期不能早于出发日期。';return}const n=Math.round((new Date(`${end}T12:00:00`)-new Date(`${start}T12:00:00`))/86400000)+1;if(n>30){error.textContent='第一版最多规划30天，请调整日期。';return}const catalog=matchingCatalog(destination),selected=state.planDestination?.name===destination?state.planDestination:null,d=catalog||selected||remoteDestination({name:destination,country:'',countryCode:state.planRegion==='国内'?'CN':'',lat:null,lon:null});const old=state.editTrip,region=state.planRegion;const generated=distributePlaces(d,n,String(data.get('pace')));const sameDestination=old&&(old.key===d.key||old.destination===d.name);const days=generated.map((places,i)=>({date:addDays(start,i),places:sameDestination&&old.days[i]?old.days[i].places:places}));const t={id:old?.id||uid(),created:old?.created||Date.now(),origin,destination:d.name||destination,key:d.key||null,destinationData:catalog?null:d,region:catalog?.region||region,start,end,people:Number(data.get('people'))||1,budget:Number(data.get('budget'))||0,days,checked:old?.checked||{},customItems:old?.customItems||[]};saveTrip(t);state.tripId=t.id;state.editTrip=null;state.planDestination=null;state.weather=null;state.weatherFor=null;goto('trip');notify(`${t.destination}的${n}天行程已保存，可以继续调整每天的地点。`);if(!d.places?.length)enrichTrip(t)}
async function loadWeather(){const t=trip();if(!t)return;const panel=document.getElementById('weatherPanel');if(!panel)return;const d=getDestination(t),today=todayISO(),horizon=addDays(today,15);if(!d?.lat||!d?.lon){panel.textContent='暂无可用坐标，天气请在出发前通过当地预报核对。';return}if(t.start>horizon){panel.textContent='旅行日期超出天气预报范围。出发前两周再来看，暂不展示猜测天气。';return}if(t.end<today){panel.textContent='这段旅行已结束，不展示当前天气预报。';return}if(state.weatherFor===t.id&&state.weather){panel.textContent='天气来自 Open-Meteo。预报可能变化，请出行前再次核对。';return}try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${d.lat}&longitude=${d.lon}&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=16`;const json=await fetchJson(url);if(trip()?.id!==t.id||state.view!=='trip')return;state.weather={};(json.daily?.time||[]).forEach((date,i)=>state.weather[date]={code:json.daily.weather_code[i],high:Math.round(json.daily.temperature_2m_max[i]),low:Math.round(json.daily.temperature_2m_min[i])});state.weatherFor=t.id;render()}catch{panel.textContent='天气服务暂时无法连接，请稍后重试。'}}
function addPlaceToTrip(p){let t=trip();const d=state.destination;if(!t||!getDestination(t)?.places?.some(x=>placeKey(x)===placeKey(p))){state.planDestination=d;state.editTrip=null;goto('plan');notify('先填写旅行日期，生成行程后就能加入地点。');return}const day=t.days.find(x=>x.places.length<2)||t.days[0];if(day.places.includes(placeKey(p))){notify('这个地方已在行程中。');return}day.places.push(placeKey(p));saveTrip(t);goto('trip');notify(`${p.name}已加入行程。`)}
function shareTrip(){const t=trip();if(!t)return;const lines=[`${t.origin} → ${t.destination}｜${t.start}—${t.end}`,`人数：${t.people}，预算：¥${t.budget}`,...t.days.map((d,i)=>`第${i+1}天 ${d.date}：${d.places.map(k=>findPlace(t,k)?.name||k.split('|')[0]).join('、')||'自由安排'}`)];const text=lines.join('\n');if(navigator.share){navigator.share({title:`向野 · ${t.destination}行程`,text}).catch(()=>{})}else if(navigator.clipboard){navigator.clipboard.writeText(text).then(()=>notify('行程文字已复制，可以发给同行的人。')).catch(()=>notify('复制失败，请检查浏览器权限。'))}else notify('当前浏览器不支持分享或复制。')}
document.addEventListener('submit',event=>{const f=event.target;if(f.id==='searchForm'){event.preventDefault();performSearch(String(new FormData(f).get('q')||''))}else if(f.id==='planForm'){event.preventDefault();createOrUpdateTrip(f)}else if(f.id==='customItemForm'){event.preventDefault();const label=String(new FormData(f).get('item')||'').trim();if(!label)return;const t=trip();if(!t)return;t.customItems=t.customItems||[];t.customItems.push({id:uid(),label:label.slice(0,80)});saveTrip(t);render();notify('已加入清单。')}});
document.addEventListener('change',event=>{const input=event.target;if(input.dataset.check){const t=trip();if(!t)return;t.checked=t.checked||{};t.checked[input.dataset.check]=input.checked;saveTrip(t);render()}});
document.addEventListener('click',event=>{const b=event.target.closest('button[data-action="detail"]');if(!b)return;const d=CATALOG[b.dataset.key]?{key:b.dataset.key,...CATALOG[b.dataset.key]}:state.destination;if(!d)return;const p=d.places?.find(x=>placeKey(x)===b.dataset.place);if(!p)return;event.stopImmediatePropagation();state.destination=d;openPlace(p)},true);
document.addEventListener('click',event=>{const b=event.target.closest('button[data-action],button[data-tab]');if(!b)return;if(b.dataset.tab){state.editTrip=null;goto(b.dataset.tab);return}const a=b.dataset.action;if(a==='home'){goto('discover')}else if(a==='profile'){goto('profile')}else if(a==='new-trip'||a==='plan'){state.editTrip=null;state.planDestination=null;goto('plan')}else if(a==='destination'||a==='all-places'){openDestination(b.dataset.key||'kyoto')}else if(a==='plan-for'){state.planDestination=state.destination;state.editTrip=null;state.planRegion=state.destination?.region||'出境';goto('plan')}else if(a==='filter-places'){state.placeTab=b.dataset.filter;render()}else if(a==='detail'){const d=state.destination||getDestination(trip())||CATALOG.kyoto;state.destination=d;const p=d.places?.find(x=>placeKey(x)===b.dataset.place);if(p)openPlace(p)}else if(a==='back-detail'){goto('destination')}else if(a==='search-result'){chooseSearchResult(Number(b.dataset.index))}else if(a==='edit-trip'){state.editTrip=trips().find(t=>t.id===b.dataset.id)||trip();state.planDestination=getDestination(state.editTrip);state.planRegion=state.editTrip?.region||'出境';goto('plan')}else if(a==='open-trip'){state.tripId=b.dataset.id||trip()?.id;goto('trip')}else if(a==='all-trips'){goto('trips')}else if(a==='open-destination'){state.destination=getDestination(trip());state.placeTab='all';goto('destination')}else if(a==='map-destination'){const d=state.destination;window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(d.name)}`,'_blank','noopener')}else if(a==='external-map'){window.open(b.dataset.url,'_blank','noopener')}else if(a==='set-region'){state.planRegion=b.dataset.region;document.querySelectorAll('[data-action="set-region"]').forEach(x=>x.classList.toggle('selected',x===b))}else if(a==='add-place'){addPlaceToTrip(state.detail)}else if(a==='choose-place'){state.chooseDay=Number(b.dataset.day);goto('choose',{tab:'trips'})}else if(a==='assign-place'){const t=trip(),day=t?.days[state.chooseDay];if(day&&!day.places.includes(b.dataset.place)){day.places.push(b.dataset.place);saveTrip(t)}goto('trip');notify('地点已加入这一天。')}else if(a==='remove-place'){const t=trip();if(!t)return;t.days[Number(b.dataset.day)].places=t.days[Number(b.dataset.day)].places.filter(x=>x!==b.dataset.place);saveTrip(t);render();notify('已从行程移除。')}else if(a==='checklist'){goto('checklist')}else if(a==='share-trip'){shareTrip()}else if(a==='remove-custom'){const t=trip();t.customItems=t.customItems.filter(x=>x.id!==b.dataset.id);saveTrip(t);render()}});
// 地球发现页和「一地慢住」叠加在原有可用行程流程之上。
const globeLabels={Egypt:'埃及',China:'中国',France:'法国',Japan:'日本',India:'印度',Italy:'意大利',Spain:'西班牙','United States of America':'美国',Australia:'澳大利亚',Canada:'加拿大',Brazil:'巴西',Norway:'挪威',Iceland:'冰岛','United Kingdom':'英国',Greece:'希腊',Turkey:'土耳其'};
const polarDestinations={
  Antarctica:{key:'polar-antarctica',name:'南极半岛',type:'region',country:'南极地区',region:'出境',center:'南极半岛',lat:-65,lon:-64,intro:'这里通常不是独立自由行目的地。可以从乌斯怀亚出发，选择南极半岛探险邮轮；航期、登陆、天气和费用需向有资质的运营方核对。给冰海、野生动物观察和船上讲座留足时间。',daily:3800,flight:13000,places:[{name:'乌斯怀亚出发港',city:'乌斯怀亚',kind:'邮轮出发地',time:'1天',cost:0,summary:'多数南极半岛探险航线从阿根廷乌斯怀亚附近出发，具体登船安排以运营方为准。'},{name:'德雷克海峡航行',city:'南极航线',kind:'探险航程',time:'约2天',cost:0,summary:'海况可能显著影响航程。探险邮轮是否登陆，取决于天气、海况及当地管理要求。'},{name:'南设得兰群岛',city:'南极半岛',kind:'极地观察',time:'半天',cost:0,summary:'部分航线可能安排登陆或冲锋舟巡游，具体不保证。'}]},
  Arctic:{key:'polar-arctic',name:'北极地区',type:'region',country:'北极地区',region:'出境',center:'斯瓦尔巴',lat:78,lon:16,intro:'北极不是单一景点。斯瓦尔巴群岛常作为探险邮轮的出发地，也可考虑陆上自然观察。航线、季节、边境和安全要求必须向官方及运营方核实。',daily:3000,flight:9000,places:[{name:'朗伊尔城',city:'斯瓦尔巴',kind:'探险门户',time:'1天',cost:0,summary:'极地活动的常见出发地。城外活动需遵循当地安全规定并选择合规向导。'},{name:'斯瓦尔巴探险邮轮',city:'斯瓦尔巴',kind:'邮轮航程',time:'多天',cost:0,summary:'可沿峡湾观察冰川与野生动物；航线和登陆点随冰况天气变化。'},{name:'峡湾与冰川观察',city:'斯瓦尔巴',kind:'自然体验',time:'半天',cost:0,summary:'尊重野生动物距离和保护区规定，不把看到特定动物当作保证。'}]}
};
function globeSpotCard(){const s=state.globeSpot;if(!s)return '<p class="globe-prompt">拖动地球，点一个地方。哪怕是海面或两极，我们也会给你一条探索线索。</p>';const d=s.destination;return `<div class="spot-card"><span class="spot-kicker">${escapeHtml(s.type)} · ${s.lat.toFixed(1)}°, ${s.lon.toFixed(1)}°</span><h2>${escapeHtml(d.name)}</h2><p>${escapeHtml(s.note)}</p><div class="actions"><button class="primary" data-action="globe-explore">看看这里</button><button class="secondary" data-action="globe-plan">规划慢住</button></div></div>`}
renderDiscover=function(){const t=trip(),near=(t&&getDestination(t))||CATALOG.kyoto;return `<p class="eyebrow">向野 · 从世界出发</p><h1 class="display">把世界转一转，<br><em>找个地方慢慢待。</em></h1><div class="globe-wrap"><div class="globe-heading"><span>01 / 世界漫游</span><span>拖动 · 点选 · 缩放</span></div><canvas id="globeCanvas" aria-label="可交互的世界地球，拖动旋转，点击选择地点"></canvas><div class="globe-zooms"><button data-globe-zoom="in" aria-label="放大地球">＋</button><button data-globe-zoom="out" aria-label="缩小地球">－</button></div><div class="globe-presets"><button data-globe-preset="30,31">埃及</button><button data-globe-preset="-72,-60">南极</button><button data-globe-preset="78,16">北极</button></div></div><div id="globeSpot">${globeSpotCard()}</div><div class="slow-banner"><span>✦ 一地慢住</span><strong>不赶下一站，也是一种旅行。</strong><p>选定一个落脚地，每隔一天安排一件事，其余时间留给街道、咖啡馆和发呆。</p><button class="text-button" data-action="slow-plan">用慢住方式规划 ↗</button></div><div class="section-heading"><h2 class="section-title">心里已有目的地？</h2></div>${searchForm()}<div class="section-heading"><h2 class="section-title">${t?'这段旅程附近值得去':'先从这里开始'}</h2><button class="text-button" data-action="all-places" data-key="${near.key||t?.key||'kyoto'}">看全部 ↗</button></div><div class="scroll-cards">${(near.places||[]).map(placeCard).join('')}</div><div class="section-heading"><h2 class="section-title">你的下一站</h2>${t?`<button class="text-button" data-action="edit-trip" data-id="${t.id}">编辑</button>`:''}</div>${t?`<div class="trip-summary"><div class="badge-date">${escapeHtml(t.start.slice(8))}<small>${escapeHtml(t.start.slice(5,7))}月</small></div><div><strong>${escapeHtml(t.origin)} → ${escapeHtml(t.destination)}</strong><p>${prettyDate(t.start)}出发 · ${duration(t)}天${t.travelStyle==='stay'?' · 一地慢住':''}</p></div><button data-action="open-trip" data-id="${t.id}">查看</button></div>`:`<div class="empty">还没有行程。转动地球，点一处你想去的地方。<p><button class="primary" data-action="plan">开始规划</button></p></div>`}`};
const previousRender=render;
render=function(){previousRender();if(state.view==='discover')window.mountXiangyeGlobe?.()};
const previousRenderPlan=renderPlan;
renderPlan=function(){const d=state.planDestination||getDestination(state.editTrip)||matchingCatalog(state.editTrip?.destination||'');const base=state.editTrip?.stayBase||d?.center||'';const style=state.editTrip?.travelStyle||state.planTravelStyle||'explore';const fields=`<div class="style-card"><span class="small muted">这段旅行怎么过</span><div class="segmented"><button type="button" data-action="travel-style" data-style="explore" class="${style==='explore'?'selected':''}">沿途探索</button><button type="button" data-action="travel-style" data-style="stay" class="${style==='stay'?'selected':''}">一地慢住</button></div><p class="small muted">慢住会以一个地方为落脚点，每隔一天只安排一个地点，其他日子留白。</p><label class="field"><span>慢住落脚地（可改成城市或街区）</span><input name="stayBase" value="${escapeHtml(base)}" placeholder="例如：开罗、京都、巴黎"></label></div>`;return previousRenderPlan().replace('<button class="primary full" type="submit">',`${fields}<button class="primary full" type="submit">`)};
const previousDistribute=distributePlaces;
distributePlaces=function(d,n,pace){if(state.planTravelStyle!=='stay')return previousDistribute(d,n,pace);const days=Array.from({length:n},()=>[]),base=state.planStayBase||d.center||d.name;const nearCenter=p=>base===d.center&&Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Number.isFinite(d.lat)&&Number.isFinite(d.lon)&&Math.hypot((p.lat-d.lat)*111,(p.lon-d.lon)*96)<36;const places=(d.places||[]).filter(p=>p.city===base||p.city?.includes(base)||base?.includes(p.city)||nearCenter(p));const pool=places.length?places:(d.places||[]).filter(p=>d.type!=='country');let j=0;for(let i=n>=4?1:0;i<n-(n>=4?1:0)&&j<pool.length;i+=2)days[i].push(placeKey(pool[j++]));return days};
const previousCreateTrip=createOrUpdateTrip;
createOrUpdateTrip=function(form){const data=new FormData(form),oldStyle=state.editTrip?.travelStyle||'explore',oldBase=state.editTrip?.stayBase||'';state.planStayBase=String(data.get('stayBase')||'').trim();state.planTravelStyle=form.querySelector('[data-action="travel-style"].selected')?.dataset.style||'explore';previousCreateTrip(form);const t=trip();if(state.view==='trip'&&t){if(state.editTrip===null&&(oldStyle!==state.planTravelStyle||oldBase&&oldBase!==state.planStayBase)){const d=getDestination(t),generated=distributePlaces(d,t.days.length,String(data.get('pace')));t.days.forEach((day,i)=>day.places=generated[i])}t.travelStyle=state.planTravelStyle;t.stayBase=state.planStayBase||getDestination(t)?.center||t.destination;saveTrip(t);render()}state.planTravelStyle=null};
document.addEventListener('xiangye:globe-select',event=>{const {lat,lon,country}=event.detail;let d,type,note;if(country==='Antarctica'||country==='Arctic'){d={...polarDestinations[country]};type='极地探索';note=country==='Antarctica'?'从乌斯怀亚出发的探险邮轮，是接近南极半岛的一种方式。':'可以从斯瓦尔巴出发，慢慢认识峡湾、冰川与极昼。'}else if(country){const key={Egypt:'egypt',China:'beijing',France:'paris',Japan:'kyoto'}[country];d=key?{key,...CATALOG[key]}:remoteDestination({name:globeLabels[country]||country,country:globeLabels[country]||country,lat,lon,countryCode:country==='China'?'CN':''});if(!key){d.lat=lat;d.lon=lon;d.center=d.name}type='陆地上的一点';note=`你点到了${d.name}。打开后会查找这个坐标附近的景点和文化地点。`}else{d=remoteDestination({name:'海上的这一点',country:'海洋',lat,lon});d.key=`ocean:${lat.toFixed(2)},${lon.toFixed(2)}`;d.type='ocean';d.intro='这里是海洋坐标，不一定有可登陆的景点。可以把它当成了解周边海域、邮轮航线与海洋文化的起点；具体航线请以运营方为准。';d.places=[{name:'海上航行体验',city:'周边海域',kind:'邮轮与航行',time:'多天',cost:0,summary:'这是方向灵感，不是实时在售航线；请按海域、季节和出发港查询合规运营方。'}];type='海洋坐标';note='这里没有陆地景点。可以看看周边海域与航行灵感，再决定从哪个港口出发。'}state.globeSpot={lat,lon,type,note,destination:d};document.getElementById('globeSpot').innerHTML=globeSpotCard()});
document.addEventListener('click',event=>{const b=event.target.closest('button[data-action]');if(!b)return;const a=b.dataset.action;if(a==='globe-explore'&&state.globeSpot){state.destination=state.globeSpot.destination;state.placeTab='all';goto('destination');if(state.destination.key?.startsWith('remote:'))loadNearby({name:state.destination.name,lat:state.destination.lat,lon:state.destination.lon})}else if(a==='globe-plan'&&state.globeSpot){state.planDestination=state.globeSpot.destination;state.editTrip=null;state.planRegion=state.planDestination.region||'出境';state.planTravelStyle='stay';goto('plan')}else if(a==='slow-plan'){state.planTravelStyle='stay';state.editTrip=null;state.planDestination=state.globeSpot?.destination||null;goto('plan')}else if(a==='travel-style'){state.planTravelStyle=b.dataset.style;document.querySelectorAll('[data-action="travel-style"]').forEach(x=>x.classList.toggle('selected',x===b))}});
render();
